import{_ as i,o as a,c as t,ae as r}from"./chunks/framework.CK6jtcgr.js";const u=JSON.parse('{"title":"Provenance, Promotion, and Reversibility","description":"","frontmatter":{},"headers":[],"relativePath":"guide/provenance-promotion-and-reversibility.md","filePath":"guide/provenance-promotion-and-reversibility.md"}'),o={name:"guide/provenance-promotion-and-reversibility.md"};function n(l,e,s,d,p,c){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="provenance-promotion-and-reversibility" tabindex="-1">Provenance, Promotion, and Reversibility <a class="header-anchor" href="#provenance-promotion-and-reversibility" aria-label="Permalink to &quot;Provenance, Promotion, and Reversibility&quot;">​</a></h1><p>SocioProphet treats provenance, promotion, and reversibility as first-class system properties.</p><h2 id="_1-provenance" tabindex="-1">1. Provenance <a class="header-anchor" href="#_1-provenance" aria-label="Permalink to &quot;1. Provenance&quot;">​</a></h2><p>Every consequential action must be attributable.</p><p>Publicly, that means the system must preserve:</p><ul><li>what happened</li><li>what inputs were used</li><li>what policy version applied</li><li>what evidence was attached</li><li>what proofs were emitted</li><li>who approved or witnessed the transition</li></ul><h2 id="_2-promotion" tabindex="-1">2. Promotion <a class="header-anchor" href="#_2-promotion" aria-label="Permalink to &quot;2. Promotion&quot;">​</a></h2><p>Promotion is not a branding flourish. It is a governance act.</p><p>Publicly, promotion must mean:</p><ul><li>prerequisites were satisfied</li><li>safety gates were green</li><li>required proofs existed</li><li>human review happened where needed</li><li>the resulting state was recorded and attributable</li></ul><h2 id="_3-reversibility" tabindex="-1">3. Reversibility <a class="header-anchor" href="#_3-reversibility" aria-label="Permalink to &quot;3. Reversibility&quot;">​</a></h2><p>Reversibility is not a sign of weakness. It is part of the safety model.</p><p>The public promise is that:</p><ul><li>harmful or invalid transitions can be reversed</li><li>evidence is not erased when reversal happens</li><li>rollback and remediation are part of the design</li><li>“we can undo this safely” is a core institutional property</li></ul><h2 id="_4-why-this-matters" tabindex="-1">4. Why this matters <a class="header-anchor" href="#_4-why-this-matters" aria-label="Permalink to &quot;4. Why this matters&quot;">​</a></h2><p>Without provenance, promotion becomes arbitrary. Without promotion rules, power becomes ambient. Without reversibility, mistakes become architecture.</p><h2 id="_5-public-safe-boundary" tabindex="-1">5. Public-safe boundary <a class="header-anchor" href="#_5-public-safe-boundary" aria-label="Permalink to &quot;5. Public-safe boundary&quot;">​</a></h2><p>We publish:</p><ul><li>the logic of proof, promotion, and reversal</li><li>the fact of witness/quorum governance</li><li>the evidence and audit model</li></ul><p>We do not publish:</p><ul><li>private signing materials</li><li>restricted operational procedures</li><li>sensitive promotion internals</li><li>private governance implementation details</li></ul><h2 id="_6-related-references" tabindex="-1">6. Related references <a class="header-anchor" href="#_6-related-references" aria-label="Permalink to &quot;6. Related references&quot;">​</a></h2><ul><li><a href="./deterministic-ai-and-mathematical-safety">Deterministic AI and Mathematical Safety</a></li><li><a href="./governed-ai-and-cybernetics">Governed AI and Cybernetics</a></li><li><a href="./authorized-cyberdefense-and-simulation">Authorized Cyberdefense and Simulation</a></li></ul>',23)])])}const m=i(o,[["render",n]]);export{u as __pageData,m as default};
